using RailwayWebBuilderCore.Enums;

namespace RailwayWebBuilderCore._SiteData.ModelRailways.Layouts;

internal class TregurraDries : LayoutBase
{
    public TregurraDries()
    {
        Name = LayoutNamesEnums.TregurraDries;
        Description = "Tregurra Dries E.C.C. (English China Clay) is two china clay works in one - on the right hand side is Treviscoe clay works and on the left hand side Moors Water clay works. Treviscoe pit was known to have been working in the 1800s, the railway line serving both the Parkandillack and Treviscoe pits; extraction of china clay was suspended around 2012 but wet mining recommenced in 2017, so it is classed as an active works. Moors Water was joined with the Liskeard and Caradon railway and linked to the Liskeard main line in 1901, the line up to Moors Water remaining as a mineral line, with the clay works closing in the 1990s and a cement depot taking its place. The scenic side of the layout is 6ft long by 2ft wide, with a fiddle yard 4ft long by 2ft wide comprising a fixed three-line section with a three-way point at the rear and a four-line traversing section at the front. Control is by Lenz 100 DCC, the buildings are all scratch built, the scenic work uses Woodland Scenics products and the backscene is an ID photographic sky scene with printed photos of china clay hills and buildings.";
    }
}
